<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue';
import type {Member} from '../composables/useWorkspace';
import {editableMember,permitted} from '../composables/roles';
const props=defineProps<{person:{identity:string;name:string};member?:Member;self?:Member;x:number;y:number;voice:boolean;showVolume?:boolean;volume:number;setVolume:(value:number)=>void;moderate:(action:string,seconds?:number)=>Promise<void>}>();
const emit=defineEmits<{close:[]}>();
const root=ref<HTMLElement>(),left=ref(props.x),top=ref(props.y),busy=ref(false),error=ref(''),chooseMute=ref(false);
const allowed=computed(()=>!!props.member&&editableMember(props.self,props.member));
const canChat=computed(()=>allowed.value&&permitted(props.self,'manage_chat'));
const canVoice=computed(()=>allowed.value&&permitted(props.self,'kick_members')&&props.voice);
async function run(action:string,seconds?:number){if(busy.value)return;busy.value=true;error.value='';try{await props.moderate(action,seconds);emit('close');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function outside(e:PointerEvent){if(!root.value?.contains(e.target as Node))emit('close');}
function key(e:KeyboardEvent){if(e.key==='Escape'){e.stopPropagation();emit('close');}}
function scroll(e:Event){if(!root.value?.contains(e.target as Node))emit('close');}
function resize(){emit('close');}
onMounted(async()=>{await nextTick();if(root.value){left.value=Math.max(8,Math.min(props.x,innerWidth-root.value.offsetWidth-8));top.value=Math.max(8,Math.min(props.y,innerHeight-root.value.offsetHeight-8));root.value.style.maxHeight=`calc(100dvh - ${top.value+8}px)`;root.value.focus();}document.addEventListener('pointerdown',outside);window.addEventListener('resize',resize);window.addEventListener('scroll',scroll,true);});
onBeforeUnmount(()=>{document.removeEventListener('pointerdown',outside);window.removeEventListener('resize',resize);window.removeEventListener('scroll',scroll,true);});
</script>
<template><Teleport to="body"><section ref="root" class="member-menu" tabindex="-1" role="dialog" :aria-label="'Участник: '+person.name" :style="{left:left+'px',top:top+'px'}" @keydown="key"><strong>{{person.name}}</strong><label v-if="voice && showVolume!==false">Громкость голоса · {{volume}}%<input type="range" min="0" max="200" step="5" :value="volume" :style="{'--range-fill': Math.max(0,Math.min(100,volume/2))+'%'}" aria-label="Громкость голоса" @input="setVolume(Number(($event.target as HTMLInputElement).value))"></label><template v-if="canChat"><button v-if="(member?.chatMutedUntil||0)>Date.now()" :disabled="busy" @click="run('unmute')">Разрешить писать</button><template v-else><button :disabled="busy" :aria-expanded="chooseMute" @click="chooseMute=!chooseMute">Запретить писать</button><div v-if="chooseMute" class="mute-durations"><button v-for="option in [{s:900,n:'15 минут'},{s:3600,n:'1 час'},{s:86400,n:'24 часа'},{s:604800,n:'1 неделя'}]" :key="option.s" :disabled="busy" @click="run('mute',option.s)">{{option.n}}</button></div></template></template><button v-if="canVoice" :disabled="busy" @click="run('kick')">Отключить от голосовой</button><p v-if="!voice&&!canChat" class="field-help">Нет доступных действий</p><p v-if="error" role="alert">{{error}}</p></section></Teleport></template>
<style scoped>.member-menu{position:fixed;z-index:180;width:252px;max-height:calc(100dvh - 16px);overflow:auto;background:#252525;padding:12px;border-radius:14px;box-shadow:0 12px 35px #0008;font-size:12px}.member-menu>strong{display:block;padding:4px 8px 12px}.member-menu>button{display:block;width:100%;text-align:left;background:transparent;padding:11px 8px;border-radius:8px}.member-menu>button:hover{background:#353535}.member-menu label{padding:8px;margin:0;font-size:11px}.member-menu input[type=range]{appearance:none;-webkit-appearance:none;margin:10px 0 0;padding:0;width:100%;height:24px;background:transparent;border-radius:0;cursor:pointer;accent-color:#66aaf0}.member-menu input[type=range]::-webkit-slider-runnable-track{height:4px;border-radius:2px;background:linear-gradient(to right,#66aaf0 0 var(--range-fill),#444 var(--range-fill) 100%)}.member-menu input[type=range]::-webkit-slider-thumb{appearance:none;-webkit-appearance:none;width:16px;height:16px;margin-top:-6px;border-radius:50%;border:2px solid #252525;background:#66aaf0}.member-menu input[type=range]::-moz-range-track{height:4px;border-radius:2px;background:#444}.member-menu input[type=range]::-moz-range-progress{height:4px;background:#66aaf0}.member-menu input[type=range]::-moz-range-thumb{width:12px;height:12px;border:2px solid #252525;border-radius:50%;background:#66aaf0}.mute-durations{display:grid;grid-template-columns:1fr 1fr;gap:5px;padding:5px 8px}.mute-durations button{font-size:11px;padding:9px}.member-menu p{font-size:11px;margin:8px;color:#d6aaaa}</style>
